-- Aprenda se Divertindo · Alternativas mais difíceis · lote 1 (100 questões)
-- Reescreve as alternativas erradas (e, em alguns casos, enxuga a certa, sem mudar o sentido).
-- A primeira opção continua sendo a correta. Pergunta, explicação e número da questão não mudam.
-- Cole tudo no SQL Editor e clique em Run. Pode rodar de novo sem problema.
update public.questoes q set opcoes = x.opcoes
  from jsonb_to_recordset($a$[{"id": 994, "opcoes": ["Retroativos (ex tunc)", "Prospectivos (ex nunc)", "Retroativos, salvo se houver dano", "Imediatos, sem retroagir"]}, {"id": 1012, "opcoes": ["Com ou sem fiança", "Somente com fiança", "Somente sem fiança", "Com fiança, só pelo juiz"]}, {"id": 1013, "opcoes": ["Dinheiro, joias, títulos ou bens", "Somente dinheiro em espécie ou depósito", "Dinheiro ou imóveis, mas não joias", "Apenas títulos da dívida pública"]}, {"id": 1093, "opcoes": ["Servidores de cargo efetivo", "Ocupantes de cargo em comissão", "Qualquer pessoa indicada", "Servidores estáveis ou temporários"]}, {"id": 1135, "opcoes": ["Aos locais de culto e às liturgias", "Aos templos registrados no Estado", "À religião oficial do país", "Às liturgias, mas não aos locais"]}, {"id": 1142, "opcoes": ["No atendimento público e privado", "No atendimento público, apenas", "No atendimento bancário, apenas", "No atendimento de saúde, apenas"]}, {"id": 1150, "opcoes": ["Agentes públicos, servidores ou não", "Apenas servidores públicos efetivos e estáveis", "Agentes públicos e particulares, indistintamente", "Apenas autoridades com poder de prender"]}, {"id": 1401, "opcoes": ["Com o constrangimento, sem precisar da vantagem", "Com a obtenção da vantagem indevida pelo autor", "Com a entrega da vantagem a um terceiro", "Com a promessa da vítima de entregar a vantagem"]}, {"id": 1409, "opcoes": ["Por qualquer pessoa do povo", "Pela vítima ou seu representante legal", "Pelo juiz, por meio de requisição", "Pelo Ministério Público, por requisição"]}, {"id": 1436, "opcoes": ["Qualquer pessoa, grupo ou ONG reconhecida", "Apenas os Estados-membros da OEA", "Apenas a vítima, por meio de advogado inscrito na OAB", "Apenas ONGs com sede no país acusado"]}, {"id": 1503, "opcoes": ["Quem está no exercício de seus direitos", "Quem tem mais de 21 anos de idade", "Quem tem advogado constituído nos autos", "Quem tem domicílio fixo no Brasil"]}, {"id": 1516, "opcoes": ["O pagamento de tributo ou penalidade", "O pagamento de tributo, mas não de penalidade", "A emissão de notas fiscais nas operações", "A escrituração dos livros fiscais exigidos"]}, {"id": 1541, "opcoes": ["Também em meios eletrônicos de acesso público", "Apenas no diário oficial impresso do próprio ente", "Somente quando algum cidadão pedir", "Somente ao Tribunal de Contas competente"]}, {"id": 1578, "opcoes": ["Pessoas físicas ou jurídicas privadas", "Órgãos públicos, sem acesso ao público", "Órgãos públicos com informação sigilosa", "Empresas públicas e de economia mista"]}, {"id": 2092, "opcoes": ["Direitos e obrigações", "Direitos civis, apenas", "Direitos políticos, apenas", "Deveres, mas não direitos"]}, {"id": 2096, "opcoes": ["Na unidade doméstica, na família ou em relação íntima de afeto", "Na unidade doméstica, desde que o agressor more com a vítima", "Somente no casamento ou na união estável formalizada em cartório", "Na família, desde que haja parentesco de sangue com a vítima"]}, {"id": 2135, "opcoes": ["A qualquer hora do dia ou da noite", "Apenas das 6h às 18h, como o mandado", "Apenas durante o dia, salvo crime hediondo", "A qualquer hora, se houver ordem do delegado"]}, {"id": 2148, "opcoes": ["Da família, da sociedade e do Estado", "Da família e do Estado, apenas", "Do Estado e da escola, apenas", "Da família e da sociedade, apenas, sem o Estado"]}, {"id": 2156, "opcoes": ["Quem exerce função pública, mesmo transitória ou sem remuneração", "Somente quem ocupa cargo efetivo, depois de aprovado em concurso", "Quem exerce função pública, desde que receba alguma remuneração", "Quem exerce função pública por mais de seis meses"]}, {"id": 2269, "opcoes": ["Sim, nos termos de lei específica", "Sim, nos termos de lei complementar", "Não, por ser serviço público essencial", "Sim, se autorizada pelo chefe do Poder"]}, {"id": 2274, "opcoes": ["Brasileiros e, na forma da lei, estrangeiros", "Apenas brasileiros natos e naturalizados", "Brasileiros e estrangeiros residentes há 1